import 'dart:io'; import 'package:flutter/foundation.dart'; import 'package:supabase_flutter/supabase_flutter.dart'; class SupabaseService { static final SupabaseClient client = Supabase.instance.client; static Future<AuthResponse> signUp(String email, String password, String fullName) async { final response = await client.auth.signUp(email: email, password: password, data: {'full_name': fullName}); if (response.user != null) { await updateProfile(response.user!.id, {'full_name': fullName, 'email': email}); } return response; } static Future<AuthResponse> signIn(String email, String password) async => await client.auth.signInWithPassword(email: email, password: password); static Future<void> signOut() async => await client.auth.signOut(); static User? get currentUser => client.auth.currentUser; static Future<Map<String, dynamic>?> getProfile(String userId) async { try { return await client.from('profiles').select().eq('id', userId).maybeSingle(); } catch (e) { return null; } } static Future<void> updateProfile(String userId, Map<String, dynamic> data) async => await client.from('profiles').upsert({'id': userId, ...data}); static Future<String?> uploadProfilePicture(String userId, dynamic fileSource) async { final fileName = userId + '_profile.jpg'; final filePath = 'avatars/' + fileName; if (kIsWeb) { await client.storage.from('profiles').uploadBinary(filePath, fileSource as Uint8List); } else { await client.storage.from('profiles').upload(filePath, fileSource as File); } return client.storage.from('profiles').getPublicUrl(filePath); } static Future<List<Map<String, dynamic>>> getItems(String table) async => await client.from(table).select(); static Future<void> addItem(String table, Map<String, dynamic> data) async => await client.from(table).insert(data); static Future<void> updateItem(String table, dynamic id, Map<String, dynamic> data) async => await client.from(table).update(data).eq('id', id); static Future<void> deleteItem(String table, dynamic id) async => await client.from(table).delete().eq('id', id); static Future<void> sendInquiry(Map<String, dynamic> data) async => await client.from('inquiries').insert(data); static Future<Map<String, dynamic>> getAppSettings() async => await client.from('app_settings').select().maybeSingle() ?? {}; static Future<void> updateAppSettings(Map<String, dynamic> data) async => await client.from('app_settings').update(data).eq('id', 1); }